74	pub(crate) struct LocalEngineBridge {
75	    pub(crate) input_address: String,
76	    pub(crate) output_address: String,
77	    pub(crate) handle: EngineHandle,
78	    pub(crate) max_model_len: u32,
79	    pub(crate) engine_index: u32,
80	    pub(crate) data_parallel_size: u32,
81	    pub(crate) metrics_watch: Option<watch::Receiver<SchedulerMetrics>>,
82	}
83	
84	impl LocalEngineBridge {
85	    pub(crate) async fn run(self, shutdown: CancellationToken) -> Result<()> {
86	        let Some(BridgeLink {
87	            mut input,
88	            output_tx,
89	            mut child_tasks,
90	        }) = connect_link(
91	            &self.input_address,
92	            &self.output_address,
93	            self.engine_index,
94	            self.data_parallel_size,
95	            self.max_model_len,
96	            self.handle.kv_capacity(),
97	            self.metrics_watch.clone(),
98	            None,
99	            &shutdown,
100	        )
101	        .await?
102	        else {
103	            return Ok(());
104	        };
105	
106	        // One shared channel carries every request's token events, tagged by
107	        // request id; this loop is the sole consumer. Per-request state lives
108	        // in `streams`, keyed by the same tag, and holds the abort reason the
109	        // scheduler observes (via `TokenSink`) when an abort flips it.
110	        let (event_tx, mut event_rx) = mpsc::unbounded_channel();
111	        let mut streams: HashMap<RequestTag, RequestStreamState> = HashMap::new();
112	
113	        info!(
114	            "local vLLM engine {} bridge connected: input={}, output={}, max_model_len={}",
115	            self.engine_index, self.input_address, self.output_address, self.max_model_len
116	        );
117	
118	        let run_result = loop {
119	            tokio::select! {
120	                biased;
121	                () = shutdown.cancelled() => break Ok(()),
122	                joined = child_tasks.join_next(), if !child_tasks.is_empty() => {
123	                    if shutdown.is_cancelled() {
124	                        break Ok(());
125	                    }
126	                    break match joined {
127	                        Some(Ok((name, Ok(())))) => {
128	                            Err(anyhow::anyhow!("local engine {name} exited unexpectedly"))
129	                        }
130	                        Some(Ok((name, Err(error)))) => {
131	                            Err(error).with_context(|| format!("local engine {name} failed"))
132	                        }
133	                        Some(Err(error)) => {
134	                            Err(anyhow::anyhow!("local engine child task panicked: {error}"))
135	                        }
136	                        None => Err(anyhow::anyhow!("local engine child task set became empty")),
137	                    };
138	                }
139	                Some(first) = event_rx.recv() => {
140	                    if let Err(error) = dispatch_burst(
141	                        self.engine_index,
142	                        first,
143	                        &mut event_rx,
144	                        &mut streams,
145	                        &output_tx,
146	                    )
147	                    {
148	                        break Err(error).context("failed to dispatch local engine output");
149	                    }
150	                }
151	                recv = input.recv() => {
152	                    let message = match recv.context("failed to receive local engine request") {
153	                        Ok(message) => message,
154	                        Err(error) => break Err(error),
155	                    };
156	                    if let Err(error) = self.handle_message(
157	                        message,
158	                        &event_tx,
159	                        &output_tx,
160	                        &mut streams,
161	                    ) {
162	                        break Err(error).context("failed to handle local engine request");
163	                    }
164	                }
165	            }
166	        };
167	
168	        // Cancel every in-flight request so the scheduler retires them on its
169	        // next emit instead of pushing into a channel no one drains.
170	        for state in streams.values() {
171	            state.abort(RequestAbortReason::Cancelled);
172	        }
173	        drop(output_tx);
174	        child_tasks.abort_all();
175	        while child_tasks.join_next().await.is_some() {}
176	
177	        run_result
178	    }
179	
180	    fn handle_message(
181	        &self,
182	        message: ZmqMessage,
183	        event_tx: &mpsc::UnboundedSender<(RequestTag, TokenEvent)>,
184	        output_tx: &mpsc::UnboundedSender<EngineCoreOutputs>,
185	        streams: &mut HashMap<RequestTag, RequestStreamState>,
186	    ) -> Result<()> {
187	        let frames = message.into_vec();
188	        if frames.len() != 2 {
189	            bail!(
190	                "expected 2 local engine request frames, got {}",
191	                frames.len()
192	            );
193	        }
194	
195	        match frames[0].as_ref() {
196	            ty if ty == EngineCoreRequestType::Add.to_frame().as_ref() => {
197	                let request: EngineCoreRequest =
198	                    vllm_engine_core_client::protocol::decode_msgpack(&frames[1])?;
199	                self.start_request(request, event_tx, output_tx, streams)
200	            }
201	            ty if ty == EngineCoreRequestType::Abort.to_frame().as_ref() => {
202	                let request_ids: Vec<String> =
203	                    vllm_engine_core_client::protocol::decode_msgpack(&frames[1])?;
204	                for request_id in request_ids {
205	                    // Drop our state first, then set the abort reason (so the
206	                    // scheduler's next emit fails and retires the request). The
207	                    // `Release` store orders the `streams.remove` before the
208	                    // reason the scheduler reads with `Acquire`; any token
209	                    // already in flight for this id is discarded by the demux
210	                    // when it finds no stream entry. An abort before the first
211	                    // token output reached the frontend is a disconnect; after
212	                    // that first token it is stream cancellation. Scheduled
213	                    // metadata can flush with the first engine output but is
214	                    // not enough to prove a client-visible token.
215	                    if let Some(state) = streams.remove(request_id.as_str()) {
216	                        let reason = if state.has_emitted_tokens {
217	                            RequestAbortReason::Cancelled
218	                        } else {
219	                            RequestAbortReason::Disconnected
220	                        };
221	                        state.abort(reason);
222	                    }
223	                }
224	                Ok(())
225	            }
226	            ty if ty == EngineCoreRequestType::Utility.to_frame().as_ref() => {
227	                let (_client_index, call_id, method_name, _args): (
228	                    u32,
229	                    UtilityCallId,
230	                    String,
231	                    rmpv::Value,
232	                ) = rmp_serde::from_slice(&frames[1])?;
233	                send_utility_response(self.engine_index, output_tx, call_id, &method_name)
234	            }
235	            other => bail!("unsupported local engine request type frame: {other:?}"),
236	        }
237	    }
238	
239	    fn start_request(
240	        &self,
241	        request: EngineCoreRequest,
242	        event_tx: &mpsc::UnboundedSender<(RequestTag, TokenEvent)>,
243	        output_tx: &mpsc::UnboundedSender<EngineCoreOutputs>,
244	        streams: &mut HashMap<RequestTag, RequestStreamState>,
245	    ) -> Result<()> {
246	        let EngineCoreRequest {
247	            request_id,
248	            prompt_token_ids,
249	            sampling_params,
250	            ..
251	        } = request;
252	        let Some(prompt_tokens) = prompt_token_ids else {
253	            warn!("request {request_id} dropped: missing prompt_token_ids");
254	            send_terminal_output(
255	                self.engine_index,
256	                output_tx,
257	                request_id,
258	                EngineCoreFinishReason::Error,
259	                None,
260	                None,
261	                None,
262	            )?;
263	            return Ok(());
264	        };
265	        let Some(sampling_params) = sampling_params else {
266	            warn!("request {request_id} dropped: missing sampling_params");
267	            send_terminal_output(
268	                self.engine_index,
269	                output_tx,
270	                request_id,
271	                EngineCoreFinishReason::Error,
272	                None,
273	                None,
274	                None,
275	            )?;
276	            return Ok(());
277	        };
278	
279	        if let Some(unsupported) = crate::vllm::wire::unsupported_request_params(&sampling_params) {
280	            warn!("request {request_id} rejected: {unsupported}");
281	            send_terminal_output(
282	                self.engine_index,
283	                output_tx,
284	                request_id,
285	                EngineCoreFinishReason::Error,
286	                None,
287	                None,
288	                None,
289	            )?;
290	            return Ok(());
291	        }
292	        let lora_adapter = match lora_adapter_from_sampling_params(&sampling_params) {
293	            Ok(adapter) => adapter,
294	            Err(error) => {
295	                let message = error.to_string();
296	                warn!("request {request_id} rejected: {message}");
297	                send_terminal_output(
298	                    self.engine_index,
299	                    output_tx,
300	                    request_id,
301	                    EngineCoreFinishReason::Error,
302	                    Some(StopReason::Text(message)),
303	                    None,
304	                    None,
305	                )?;
306	                return Ok(());
307	            }
308	        };
309	        let kv_transfer_params = sampling_params
310	            .extra_args
311	            .as_ref()
312	            .and_then(|args| args.get("kv_transfer_params"))
313	            .cloned();
314	        let stop_sentinel_id = stop_sentinel_id(
315	            sampling_params.eos_token_id,
316	            &sampling_params.stop_token_ids,
317	        );
318	
319	        let tag: RequestTag = Arc::from(request_id.as_str());
320	        let abort_reason = Arc::new(AtomicU8::new(RequestAbortReason::None as u8));
321	        let token_tx = TokenSink::new(tag.clone(), event_tx.clone(), Arc::clone(&abort_reason));
322	        // Open the request's root span here, before submit, so its context can
323	        // travel into the scheduler as the parent of the queue/prefill/decode
324	        // spans. When tracing is off we must build a *noop* span rather than a
325	        // real one: fastrace is compiled with `enable`, so `Span::root` with a
326	        // sampled context always allocates and reports. Gating on `is_enabled()`
327	        // keeps the default (tracing-off) path free of per-request span work,
328	        // and `from_span` on a noop span yields `None` so the scheduler skips
329	        // its span work too.
330	        let trace_root = if crate::tracing_state::is_enabled() {
331	            Span::root("request", SpanContext::random())
332	                .with_property(|| ("request_id", tag.to_string()))
333	        } else {
334	            Span::noop()
335	        };
336	        let trace_parent = SpanContext::from_span(&trace_root);
337	        self.handle
338	            .submit(GenerateRequest {
339	                trace_parent,
340	                request_id: Some(request_id),
341	                queued_at_unix_s: Some(request.arrival_time),
342	                data_parallel_rank: Some(self.engine_index as usize),
343	                prompt_tokens,
344	                params: convert_sampling(&sampling_params),
345	                max_tokens: sampling_params.max_tokens as usize,
346	                lora_adapter,
347	                kv_transfer_params,
348	                token_tx,
349	                logprobs: requested_logprobs(&sampling_params),
350	                prompt_logprobs: requested_prompt_logprobs(&sampling_params),
351	            })
352	            .context("failed to submit request to scheduler")?;
353	
354	        streams.insert(
355	            tag,
356	            RequestStreamState::new(abort_reason, trace_root, stop_sentinel_id),
357	        );
358	        Ok(())
359	    }
360	}
