362	/// Per-request demux state held by the bridge loop, keyed by [`RequestTag`].
363	/// Replaces the former per-request task's locals; `first_token_*` flush onto
364	/// the request's first output, `abort_reason` is the state the scheduler's
365	/// [`TokenSink`] checks so an abort retires the request without closing the
366	/// shared channel.
367	struct RequestStreamState {
368	    first_token_events: Option<Vec<EngineCoreEvent>>,
369	    first_token_prefill_stats: Option<PrefillStats>,
370	    /// P/D handoff metadata can arrive in a burst with no token or terminal
371	    /// event, so retain it until the next output carries it to the router.
372	    kv_transfer_params: Option<serde_json::Value>,
373	    /// The vLLM text decoder removes the final token from a stop-finished
374	    /// output. Keep an EOS or explicit stop token as that removable sentinel.
375	    stop_sentinel_id: Option<u32>,
376	    abort_reason: Arc<AtomicU8>,
377	    has_emitted_tokens: bool,
378	    /// Request-lifetime root span (submit → finish). The scheduler opens
379	    /// queue/prefill/decode as children of this via the `SpanContext` passed in
380	    /// `GenerateRequest.trace_parent`, so the host-side phase breakdown is timed
381	    /// where the work actually happens (inside the scheduler), not inferred from
382	    /// event arrival at this downstream demux. `Span::noop()` when tracing is
383	    /// off. Held only for its `Drop`: dropping this state (on request completion
384	    /// or abort) ends the root span and closes the trace.
385	    #[allow(dead_code)]
386	    trace_root: Span,
387	}
388	
389	impl RequestStreamState {
390	    fn new(abort_reason: Arc<AtomicU8>, trace_root: Span, stop_sentinel_id: Option<u32>) -> Self {
391	        Self {
392	            first_token_events: None,
393	            first_token_prefill_stats: None,
394	            kv_transfer_params: None,
395	            stop_sentinel_id,
396	            abort_reason,
397	            has_emitted_tokens: false,
398	            trace_root,
399	        }
400	    }
401	
402	    fn abort(&self, reason: RequestAbortReason) {
403	        reason.store(&self.abort_reason);
404	    }
405	}
