407	/// Drain the ready burst from the shared token channel (the `first` event plus
408	/// everything already queued), bucket it per request preserving event order,
409	/// fold each request's events into at most one `EngineCoreOutput`, and ship the
410	/// whole burst as a single `EngineCoreOutputs` — collapsing what used to be N
411	/// per-request ZMQ messages per step into one.
412	fn dispatch_burst(
413	    engine_index: u32,
414	    first: (RequestTag, TokenEvent),
415	    event_rx: &mut TokenStreamReceiver,
416	    streams: &mut HashMap<RequestTag, RequestStreamState>,
417	    output_tx: &mpsc::UnboundedSender<EngineCoreOutputs>,
418	) -> Result<()> {
419	    // Bucket the burst by request, keeping first-seen order so outputs are
420	    // deterministic and each request's events stay in arrival order.
421	    let mut order: Vec<RequestTag> = Vec::new();
422	    let mut buckets: HashMap<RequestTag, Vec<TokenEvent>> = HashMap::new();
423	    let mut bucket = |tag: RequestTag, event: TokenEvent| {
424	        if let Some(events) = buckets.get_mut(&tag) {
425	            events.push(event);
426	        } else {
427	            order.push(Arc::clone(&tag));
428	            buckets.insert(tag, vec![event]);
429	        }
430	    };
431	    bucket(first.0, first.1);
432	    while let Ok((tag, event)) = event_rx.try_recv() {
433	        bucket(tag, event);
434	    }
435	
436	    let mut outputs: Vec<EngineCoreOutput> = Vec::with_capacity(order.len());
437	    let mut finished_requests: BTreeSet<String> = BTreeSet::new();
438	    for tag in order {
439	        let events = buckets.remove(&tag).expect("bucket for ordered tag");
440	        // No stream entry means the request was aborted or already finished;
441	        // its late events are dropped.
442	        let Some(state) = streams.get_mut(&tag) else {
443	            continue;
444	        };
445	        let (output, terminated) = reduce_request(&tag, state, events);
446	        if let Some(output) = output {
447	            if !output.new_token_ids.is_empty() {
448	                state.has_emitted_tokens = true;
449	            }
450	            outputs.push(output);
451	        }
452	        if terminated {
453	            // Dropping the state ends both spans, closing the request trace.
454	            streams.remove(&tag);
455	            finished_requests.insert(tag.to_string());
456	        }
457	    }
458	
459	    if outputs.is_empty() {
460	        return Ok(());
461	    }
462	    send_outputs(
463	        output_tx,
464	        RequestBatchOutputs {
465	            engine_index,
466	            outputs,
467	            finished_requests: (!finished_requests.is_empty()).then_some(finished_requests),
468	            timestamp: now_secs_f64(),
469	            ..Default::default()
470	        }
471	        .into(),
472	    )
473	}
