475	/// Fold one request's events from a single burst into at most one output.
476	/// Tokens coalesce, and a trailing terminal rides the same output carrying its
477	/// finish reason; `first_token_events`/`prefill_stats` flush onto whichever
478	/// output goes first. A lone `Scheduled` (no token, no terminal) yields no
479	/// output — its metadata waits in `state` for the first real output. Returns
480	/// `(output, terminated)`.
481	fn reduce_request(
482	    request_id: &str,
483	    state: &mut RequestStreamState,
484	    events: Vec<TokenEvent>,
485	) -> (Option<EngineCoreOutput>, bool) {
486	    let mut token_ids: Vec<u32> = Vec::new();
487	    let mut positions: Vec<PositionLogprobs> = Vec::new();
488	    let mut has_logprobs = false;
489	    let mut finish_reason: Option<EngineCoreFinishReason> = None;
490	    let mut stop_reason: Option<StopReason> = None;
491	    let mut terminated = false;
492	
493	    for event in events {
494	        match event {
495	            TokenEvent::Scheduled {
496	                queued_at_unix_s,
497	                scheduled_at_unix_s,
498	                prompt_tokens,
499	                cached_tokens,
500	            } => {
501	                state.first_token_events = Some(vec![
502	                    EngineCoreEvent {
503	                        r#type: EngineCoreEventType::Queued,
504	                        timestamp: queued_at_unix_s,
505	                    },
506	                    EngineCoreEvent {
507	                        r#type: EngineCoreEventType::Scheduled,
508	                        timestamp: scheduled_at_unix_s,
509	                    },
510	                ]);
511	                // Upstream invariant: computed (actual prefill work) +
512	                // cached (prefix-cache hit) == prompt; double-counting skews
513	                // the per-source prompt token metrics.
514	                state.first_token_prefill_stats = Some(PrefillStats {
515	                    num_prompt_tokens: prompt_tokens as u32,
516	                    num_computed_tokens: prompt_tokens.saturating_sub(cached_tokens) as u32,
517	                    num_cached_tokens: cached_tokens as u32,
518	                    num_local_cached_tokens: cached_tokens as u32,
519	                    num_external_cached_tokens: 0,
520	                    num_cache_creation_tokens: 0,
521	                });
522	            }
523	            TokenEvent::Token { id, logprob } => {
524	                token_ids.push(id);
525	                if let Some(position) = to_wire_position_logprobs(id, logprob) {
526	                    has_logprobs = true;
527	                    positions.push(position);
528	                } else {
529	                    positions.push(PositionLogprobs {
530	                        entries: Vec::new(),
531	                    });
532	                }
533	            }
534	            TokenEvent::PromptTokens { .. } => {
535	                // Legacy model lines reject prompt-logprob requests at admission.
536	            }
537	            TokenEvent::KvTransfer { params } => {
538	                state.kv_transfer_params = Some(params);
539	            }
540	            TokenEvent::Finished {
541	                finish_reason: fr, ..
542	            } => {
543	                // PegaInfer suppresses EOS before emitting TokenEvents, while
544	                // vLLM's text decoder expects the terminal Stop output to
545	                // contain EOS and unconditionally removes its final token.
546	                // Without this protocol token, a speculative step that commits
547	                // [visible token, EOS] loses the visible token at the frontend.
548	                if fr == FinishReason::Stop
549	                    && let Some(stop_sentinel_id) = state.stop_sentinel_id
550	                {
551	                    token_ids.push(stop_sentinel_id);
552	                    positions.push(PositionLogprobs {
553	                        entries: Vec::new(),
554	                    });
555	                }
556	                finish_reason = Some(convert_finish_reason(fr));
557	                terminated = true;
558	            }
559	            TokenEvent::Error { message, .. } => {
560	                warn!("request {request_id} failed: {message}");
561	                finish_reason = Some(EngineCoreFinishReason::Error);
562	                stop_reason = Some(StopReason::Text(message));
563	                terminated = true;
564	            }
565	            TokenEvent::Rejected { message, .. } => {
566	                // Rejected means the request could not be admitted, not that it
567	                // completed cleanly.
568	                warn!("request {request_id} rejected: {message}");
569	                finish_reason = Some(EngineCoreFinishReason::Error);
570	                stop_reason = Some(StopReason::Text(message));
571	                terminated = true;
572	            }
573	        }
574	    }
575	
576	    if token_ids.is_empty() && !terminated {
577	        return (None, false);
578	    }
579	
580	    let logprobs = has_logprobs.then_some(MaybeWireLogprobs::Direct(Logprobs { positions }));
581	    let mut output = engine_output(
582	        request_id.to_string(),
583	        token_ids,
584	        logprobs,
