598	/// vLLM `SchedulerStats` view of a load snapshot — what the frontend's
599	/// Prometheus gauges (`scheduler_running`, `scheduler_waiting`,
600	/// `kv_cache_usage`) and DP load balancer consume.
601	pub(crate) fn scheduler_stats_from(snapshot: &SchedulerMetrics) -> SchedulerStats {
602	    SchedulerStats {
603	        num_running_reqs: snapshot.num_running_reqs,
604	        num_waiting_reqs: snapshot.num_waiting_reqs,
605	        kv_cache_usage: if snapshot.kv_total_blocks == 0 {
606	            0.0
607	        } else {
608	            snapshot.kv_used_blocks as f64 / snapshot.kv_total_blocks as f64
609	        },
610	        ..SchedulerStats::default()
611	    }
612	}
