614	/// Per-interval spec-decode delta from two cumulative snapshots, in the wire
615	/// shape the frontend increments its `vllm:spec_decode_*_total` counters by (see
616	/// [`SpecDecodeCounters`] for why the transport carries totals and the wire
617	/// carries deltas).
618	fn spec_decode_delta(last: &SpecDecodeCounters, cur: &SpecDecodeCounters) -> SpecDecodingStats {
619	    let num_accepted_tokens_per_pos = cur
620	        .num_accepted_tokens_per_pos
621	        .iter()
622	        .zip(&last.num_accepted_tokens_per_pos)
623	        .map(|(cur_pos, last_pos)| cur_pos.saturating_sub(*last_pos))
624	        .take(cur.num_spec_tokens as usize)
625	        .collect();
626	    SpecDecodingStats {
627	        num_spec_tokens: cur.num_spec_tokens,
628	        num_drafts: cur.num_drafts.saturating_sub(last.num_drafts),
629	        num_draft_tokens: cur.num_draft_tokens.saturating_sub(last.num_draft_tokens),
630	        num_accepted_tokens: cur
631	            .num_accepted_tokens
632	            .saturating_sub(last.num_accepted_tokens),
633	        num_accepted_tokens_per_pos,
634	    }
635	}
636	
637	/// Per-interval prefix-cache deltas from two cumulative snapshots, in the wire
638	/// shape the frontend increments its prefix-cache counters by. The frontend
639	/// credits every local hit to `source="device"` and reads a tier split only off
640	/// the connector stats, so connector-restored hits travel there, the way vLLM's
641	/// own offload connector reports them: local stats carry the remaining hits
642	/// into `vllm:prefix_cache_*` and `source="device"`, connector stats carry the
643	/// connector lookups and hits into `vllm:external_prefix_cache_*`, with hits
644	/// labeled `source="host"` when the engine knows they came from host memory
645	/// and `source="external_unspecified"` when it cannot say which tier.
646	/// The connector side is `None` for an interval without host activity. A total
647	/// below its baseline means the engine restarted, so the interval diffs from
648	/// zero rather than going negative or dropping the new counts.
649	fn prefix_cache_delta(
650	    last: &PrefixCacheCounters,
651	    cur: &PrefixCacheCounters,
652	) -> (PrefixCacheStats, Option<PrefixCacheStats>) {
653	    let restarted = cur.queries < last.queries
654	        || cur.hits < last.hits
655	        || cur.host_queries < last.host_queries
656	        || cur.host_hits < last.host_hits
657	        || cur.external_unspecified_hits < last.external_unspecified_hits;
658	    let base = if restarted {
659	        PrefixCacheCounters::default()
660	    } else {
661	        *last
662	    };
663	    let hits = cur.hits - base.hits;
664	    let host_queries = cur.host_queries - base.host_queries;
665	    let host_hits = cur.host_hits - base.host_hits;
666	    let unspecified_hits = cur.external_unspecified_hits - base.external_unspecified_hits;
667	    let external_hits = host_hits + unspecified_hits;
668	    let local = PrefixCacheStats {
669	        base: BaseCacheStats {
670	            queries: cur.queries - base.queries,
671	            hits: hits.saturating_sub(external_hits),
672	            ..BaseCacheStats::default()
673	        },
674	        ..PrefixCacheStats::default()
675	    };
676	    let connector = (host_queries > 0 || external_hits > 0).then(|| PrefixCacheStats {
677	        base: BaseCacheStats {
678	            queries: host_queries,
679	            hits: external_hits,
680	            ..BaseCacheStats::default()
681	        },
682	        hits_by_source: CachedTokensBySource {
683	            host: host_hits,
684	            external_unspecified: unspecified_hits,
685	            ..CachedTokensBySource::default()
686	        },
687	        ..PrefixCacheStats::default()
688	    });
689	    (local, connector)
690	}
