692	/// Turns the scheduler's cumulative counters into the per-interval deltas
693	/// stamped on each outgoing batch.
694	#[derive(Default)]
695	pub(crate) struct StatsTracker {
696	    spec_decode: SpecDecodeCounters,
697	    prefix_cache: PrefixCacheCounters,
698	}
699	
700	impl StatsTracker {
701	    /// Stats for the next outgoing batch. Advances the baselines, so a caller
702	    /// that declines to send after calling this drops only that interval's
703	    /// counter deltas.
704	    pub(crate) fn stats(&mut self, snapshot: &SchedulerMetrics) -> SchedulerStats {
705	        let mut stats = scheduler_stats_from(snapshot);
706	        stats.spec_decoding_stats = self.spec_decode_interval(snapshot);
707	        if let Some(cur) = &snapshot.prefix_cache {
708	            (stats.prefix_cache_stats, stats.connector_prefix_cache_stats) =
709	                prefix_cache_delta(&self.prefix_cache, cur);
710	            self.prefix_cache = *cur;
711	        } else {
712	            // Reset so a prefix cache that shows up later diffs from zero.
713	            self.prefix_cache = PrefixCacheCounters::default();
714	        }
715	        stats
716	    }
717	
718	    /// The spec-decode delta, or `None` when nothing drafted.
719	    fn spec_decode_interval(&mut self, snapshot: &SchedulerMetrics) -> Option<SpecDecodingStats> {
720	        let Some(cur) = &snapshot.spec_decode else {
721	            // Reset so a drafter loaded later diffs from zero.
722	            self.spec_decode = SpecDecodeCounters::default();
723	            return None;
724	        };
725	        let delta = spec_decode_delta(&self.spec_decode, cur);
726	        self.spec_decode = *cur;
727	        // A zero-draft interval would divide by zero in the frontend's
728	        // acceptance-rate log, and every counter moves only inside
729	        // `observe_draft`, so dropping it loses nothing.
730	        (delta.num_drafts > 0).then_some(delta)
731	    }
732	}
733	
734	/// Forward every scheduler load snapshot as a stats-only output batch; the
735	/// frontend records it into the shared Prometheus registry. Sends the current
736	/// snapshot up front so the gauges initialize before the first step, then one
737	/// message per watch change until shutdown. Losing either output or scheduler
738	/// load feed is fatal because keeping that engine registered would leave stale
739	/// metrics and a request-routing black hole.
740	async fn publish_scheduler_stats(
741	    engine_index: u32,
742	    mut load_rx: watch::Receiver<SchedulerMetrics>,
743	    output_tx: mpsc::UnboundedSender<EngineCoreOutputs>,
744	    shutdown: CancellationToken,
745	) -> Result<()> {
746	    let mut tracker = StatsTracker::default();
747	    loop {
748	        let snapshot = *load_rx.borrow_and_update();
749	        let stats = tracker.stats(&snapshot);
750	        let outputs = RequestBatchOutputs {
751	            engine_index,
752	            scheduler_stats: Some(Box::new(stats)),
753	            timestamp: now_secs_f64(),
754	            ..Default::default()
755	        }
756	        .into();
757	        send_outputs(&output_tx, outputs).context("failed to publish scheduler stats")?;
758	        tokio::select! {
759	            biased;
760	            () = shutdown.cancelled() => return Ok(()),
761	            changed = load_rx.changed() => {
762	                changed.context("scheduler load feed closed")?;
763	            }
764	        }
765	    }
766	}
