768	/// The connected transport of one engine bridge: the vLLM EngineCore
769	/// handshake done, the output pump running, the stats publisher attached.
770	/// Shared by the legacy per-token bridge and the stepped bridge — everything
771	/// north of the engine data plane is identical between them.
772	struct BridgeLink {
773	    input: DealerSocket,
774	    output_tx: mpsc::UnboundedSender<EngineCoreOutputs>,
775	    child_tasks: tokio::task::JoinSet<(&'static str, Result<()>)>,
