778	#[allow(clippy::too_many_arguments)]
779	async fn connect_link(
780	    input_address: &str,
781	    output_address: &str,
782	    engine_index: u32,
783	    data_parallel_size: u32,
784	    max_model_len: u32,
785	    kv_capacity: Option<crate::engine::KvCapacity>,
786	    metrics_watch: Option<watch::Receiver<SchedulerMetrics>>,
787	    engine_dead: Option<CancellationToken>,
788	    shutdown: &CancellationToken,
789	) -> Result<Option<BridgeLink>> {
790	    let engine_id = EngineId::from_engine_index(
791	        u16::try_from(engine_index).context("engine_index exceeds u16 EngineId")?,
792	    );
793	    let mut socket_options = SocketOptions::default();
794	    socket_options.peer_identity(PeerIdentity::try_from(engine_id)?);
795	
796	    let (num_gpu_blocks, block_size, kv_cache_size_tokens, kv_cache_max_concurrency) =
797	        match kv_capacity {
798	            Some(c) => {
799	                // vLLM single-group concurrency: blocks / ceil(max_len / block_size).
800	                let blocks_per_req = u64::from(max_model_len).div_ceil(c.block_size as u64);
801	                (
802	                    c.total_blocks as u64,
803	                    c.block_size as u64,
804	                    Some(c.total_tokens() as u64),
805	                    Some(c.total_blocks as f64 / blocks_per_req as f64),
806	                )
807	            }
808	            None => (0, 16, None, None),
809	        };
810	    let ready = EngineCoreReadyResponse {
811	        max_model_len: u64::from(max_model_len),
812	        num_gpu_blocks,
813	        block_size,
814	        dp_stats_address: None,
815	        dtype: ModelDtype::BFloat16,
816	        vllm_version: "pegainfer-local-bridge".to_string(),
817	        world_size: 1,
818	        effective_data_parallel_size: u64::from(data_parallel_size),
819	        tensor_parallel_size: 1,
820	        pipeline_parallel_size: 1,
821	        decode_context_parallel_size: 1,
822	        data_parallel_rank: engine_index,
823	        // Discovery metadata for gRPC control; HTTP completions do not admit
824	        // against these caps. Keep them above any sim concurrency we bench.
825	        max_num_seqs: 8192,
826	        max_num_batched_tokens: u64::from(max_model_len),
827	        instance_id: format!("pegainfer-local-{engine_index}"),
828	        supports_lora: false,
829	        max_loras: 0,
830	        kv_cache_size_tokens,
831	        kv_cache_max_concurrency,
832	        effective_attention_block_size: kv_capacity.map(|c| c.block_size as u64),
833	        kv_events_config: None,
834	        weight_transfer_backend: None,
835	        enable_sleep_mode: false,
836	        supports_draft_weight_updates: false,
837	    };
838	    info!(
839	        "local engine {engine_index} KV capacity: {kv_capacity:?} -> \
840	         kv_cache_size_tokens={kv_cache_size_tokens:?} \
841	         kv_cache_max_concurrency={kv_cache_max_concurrency:?}"
842	    );
843	    let mut input = DealerSocket::with_options(socket_options);
844	    let mut output = PushSocket::new();
845	    let handshake = async {
846	        input
847	            .connect(input_address)
848	            .await
849	            .with_context(|| format!("failed to connect local engine input {input_address}"))?;
850	        input
851	            .send(ZmqMessage::from(encode_msgpack(&ready)?))
852	            .await
853	            .context("failed to send local engine ready response")?;
854	        output
855	            .connect(output_address)
856	            .await
857	            .with_context(|| format!("failed to connect local engine output {output_address}"))
858	    };
859	    // zeromq retries a refused connect for 30 s, which outlives a server that
860	    // failed its own startup and closed the listeners.
861	    tokio::select! {
862	        biased;
863	        () = shutdown.cancelled() => return Ok(None),
864	        handshake = handshake => handshake?,
865	    }
866	
867	    let (output_tx, output_rx) = mpsc::unbounded_channel();
868	    let mut child_tasks = tokio::task::JoinSet::new();
869	    child_tasks.spawn(async move {
870	        (
871	            "output sender",
872	            output_loop(output, output_rx, engine_dead).await,
873	        )
874	    });
875	
876	    // Legacy handle engines republish load snapshots as stats-only output
877	    // batches: their scheduler loops park when idle, so the watch cadence is
878	    // bounded. The stepped bridge passes no watch here — its driver busy-polls
879	    // (every spin would become a message), so it reads the watch at send time
880	    // and stamps stats onto the batches it already emits instead.
881	    if let Some(load_rx) = metrics_watch {
882	        let stats_output_tx = output_tx.clone();
883	        let stats_shutdown = shutdown.clone();
884	        child_tasks.spawn(async move {
885	            (
886	                "scheduler stats publisher",
887	                publish_scheduler_stats(engine_index, load_rx, stats_output_tx, stats_shutdown)
888	                    .await,
889	            )
890	        });
891	    }
892	
893	    Ok(Some(BridgeLink {
894	        input,
895	        output_tx,
896	        child_tasks,
897	    }))
898	}
