900	async fn output_loop(
901	    mut output: PushSocket,
902	    mut output_rx: mpsc::UnboundedReceiver<EngineCoreOutputs>,
903	    engine_dead: Option<CancellationToken>,
904	) -> Result<()> {
905	    while let Some(outputs) = output_rx.recv().await {
906	        output
907	            .send(ZmqMessage::from(encode_msgpack(&outputs)?))
908	            .await
909	            .context("failed to send local engine output")?;
910	    }
911	    // Sent after the queued outputs: the client then fails every request it
912	    // still tracks, including ones the bridge never read.
913	    if engine_dead
914	        .as_ref()
915	        .is_some_and(CancellationToken::is_cancelled)
916	    {
917	        output
918	            .send(ZmqMessage::from(ENGINE_CORE_DEAD_SENTINEL.to_vec()))
919	            .await
920	            .context("failed to send the engine dead sentinel")?;
921	    }
922	    Ok(())
923	}
