73	pub(crate) struct SteppedEngineBridge {
74	    pub(crate) input_address: String,
75	    pub(crate) output_address: String,
76	    pub(crate) scheduler: SchedulerHandle,
77	    pub(crate) kv_capacity: Option<KvCapacity>,
78	    pub(crate) max_model_len: u32,
79	    pub(crate) engine_index: u32,
80	    pub(crate) data_parallel_size: u32,
81	}
82	
83	impl SteppedEngineBridge {
84	    pub(crate) async fn run(mut self, shutdown: CancellationToken) -> Result<()> {
85	        let engine_dead = CancellationToken::new();
86	        let mut steps = self
87	            .scheduler
88	            .take_steps()
89	            .context("partition step stream already taken")?;
90	        let mut tracker = StatsTracker::default();
91	        let Some(BridgeLink {
92	            mut input,
93	            output_tx,
94	            mut child_tasks,
95	        }) = connect_link(
96	            &self.input_address,
97	            &self.output_address,
98	            self.engine_index,
99	            self.data_parallel_size,
100	            self.max_model_len,
101	            self.kv_capacity,
102	            None,
103	            Some(engine_dead.clone()),
104	            &shutdown,
105	        )
106	        .await?
107	        else {
108	            return Ok(());
109	        };
110	        send_outputs(
111	            &output_tx,
112	            RequestBatchOutputs {
113	                engine_index: self.engine_index,
114	                scheduler_stats: Some(Box::new(self.stats(&mut tracker))),
115	                timestamp: now_secs_f64(),
116	                ..Default::default()
117	            }
118	            .into(),
119	        )?;
120	
121	        let anchor = UnixAnchor::now();
122	        let mut streams: HashMap<RequestId, SteppedStream> = HashMap::new();
123	        let mut names: HashMap<String, RequestId> = HashMap::new();
124	
125	        info!(
126	            "local vLLM engine {} stepped bridge connected: input={}, output={}, max_model_len={}",
127	            self.engine_index, self.input_address, self.output_address, self.max_model_len
128	        );
129	
130	        let run_result = loop {
131	            tokio::select! {
132	                biased;
133	                () = shutdown.cancelled() => break Ok(()),
134	                joined = child_tasks.join_next(), if !child_tasks.is_empty() => {
135	                    if shutdown.is_cancelled() {
136	                        break Ok(());
137	                    }
138	                    break match joined {
139	                        Some(Ok((name, Ok(())))) => {
140	                            Err(anyhow::anyhow!("local engine {name} exited unexpectedly"))
141	                        }
142	                        Some(Ok((name, Err(error)))) => {
143	                            Err(error).with_context(|| format!("local engine {name} failed"))
144	                        }
145	                        Some(Err(error)) => {
146	                            Err(anyhow::anyhow!("local engine child task panicked: {error}"))
147	                        }
148	                        None => Err(anyhow::anyhow!("local engine child task set became empty")),
149	                    };
150	                }
151	                Some(step) = steps.recv() => {
152	                    if let Err(error) = self.dispatch_step(
153	                        step,
154	                        &anchor,
155	                        &mut streams,
156	                        &mut names,
157	                        &mut tracker,
158	                        &output_tx,
159	                    ) {
160	                        break Err(error).context("failed to dispatch local engine step");
161	                    }
162	                }
163	                () = self.scheduler.exited() => {
164	                    // Dispatch what the driver committed before it exited first.
165	                    if !steps.is_empty() {
166	                        continue;
167	                    }
168	                    break Err(anyhow::anyhow!("scheduler exited"));
169	                }
170	                recv = input.recv() => {
171	                    let message = match recv.context("failed to receive local engine request") {
172	                        Ok(message) => message,
173	                        Err(error) => break Err(error),
174	                    };
175	                    if let Err(error) = self.handle_message(
176	                        message,
177	                        &mut streams,
178	                        &mut names,
179	                        &output_tx,
180	                    ) {
181	                        break Err(error).context("failed to handle local engine request");
182	                    }
183	                }
184	            }
185	        };
186	
187	        // Flip every in-flight request's abort flag so the scheduler retires
188	        // them on its next touch; dropping the partition handle afterwards
189	        // disconnects the submission channel and lets the driver drain out.
190	        for state in streams.values() {
191	            state.control.abort();
192	        }
193	        if run_result.is_err() {
194	            engine_dead.cancel();
195	        }
196	        drop(output_tx);
197	        // Deliver what is already queued, and after a failure the dead engine
198	        // notice, before stopping the link.
199	        if tokio::time::timeout(OUTPUT_DRAIN_TIMEOUT, async {
200	            while child_tasks.join_next().await.is_some() {}
201	        })
202	        .await
203	        .is_err()
204	        {
205	            warn!(
206	                "local engine {} output did not drain in time",
207	                self.engine_index
208	            );
209	        }
210	        child_tasks.abort_all();
211	        while child_tasks.join_next().await.is_some() {}
212	
213	        run_result
214	    }
215	
216	    /// Stats for an outgoing batch; the counter deltas run from the last
217	    /// batch stamped, not the last step run.
218	    fn stats(&self, tracker: &mut StatsTracker) -> SchedulerStats {
219	        tracker.stats(&self.scheduler.metrics())
220	    }
221	
222	    fn dispatch_step(
223	        &self,
224	        step: StepOutputs,
225	        anchor: &UnixAnchor,
226	        streams: &mut HashMap<RequestId, SteppedStream>,
227	        names: &mut HashMap<String, RequestId>,
228	        tracker: &mut StatsTracker,
229	        output_tx: &tokio::sync::mpsc::UnboundedSender<
230	            vllm_engine_core_client::protocol::output::EngineCoreOutputs,
231	        >,
232	    ) -> Result<()> {
233	        let mut outputs: Vec<EngineCoreOutput> = Vec::with_capacity(step.updates.len());
234	        let mut finished_requests: BTreeSet<String> = BTreeSet::new();
235	        for update in step.updates {
236	            // No stream entry means the request was aborted or already
237	            // finished; late updates (including retire-window drop bombs) are
238	            // dropped.
239	            let Some(state) = streams.get_mut(&update.id) else {
240	                continue;
241	            };
242	            let id = update.id;
243	            let (output, terminated) = reduce_update(state, update, anchor);
244	            if let Some(output) = output {
245	                outputs.push(output);
246	            }
247	            if terminated {
248	                // Dropping the state ends the root span, closing the trace.
249	                let state = streams.remove(&id).expect("terminated stream present");
250	                names.remove(&state.request_id);
251	                finished_requests.insert(state.request_id);
252	            }
253	        }
254	
255	        send_outputs(
256	            output_tx,
257	            RequestBatchOutputs {
258	                engine_index: self.engine_index,
259	                outputs,
260	                finished_requests: (!finished_requests.is_empty()).then_some(finished_requests),
261	                scheduler_stats: Some(Box::new(self.stats(tracker))),
262	                timestamp: now_secs_f64(),
263	                weight_version: None,
264	            }
265	            .into(),
266	        )
267	    }
268	
269	    fn handle_message(
270	        &self,
271	        message: ZmqMessage,
272	        streams: &mut HashMap<RequestId, SteppedStream>,
273	        names: &mut HashMap<String, RequestId>,
274	        output_tx: &tokio::sync::mpsc::UnboundedSender<
275	            vllm_engine_core_client::protocol::output::EngineCoreOutputs,
276	        >,
277	    ) -> Result<()> {
278	        let frames = message.into_vec();
279	        if frames.len() != 2 {
280	            bail!(
281	                "expected 2 local engine request frames, got {}",
282	                frames.len()
283	            );
284	        }
285	
286	        match frames[0].as_ref() {
287	            ty if ty == EngineCoreRequestType::Add.to_frame().as_ref() => {
288	                let request: EngineCoreRequest =
289	                    vllm_engine_core_client::protocol::decode_msgpack(&frames[1])?;
290	                self.start_request(request, streams, names, output_tx)
291	            }
292	            ty if ty == EngineCoreRequestType::Abort.to_frame().as_ref() => {
293	                let request_ids: Vec<String> =
294	                    vllm_engine_core_client::protocol::decode_msgpack(&frames[1])?;
295	                for request_id in request_ids {
296	                    // Drop our state first, then flip the abort flag (whose
297	                    // `Release` store orders after the removal); the
298	                    // scheduler's next touch retires the request, and any
299	                    // update already in flight finds no stream entry.
300	                    let Some(id) = names.remove(&request_id) else {
301	                        continue;
302	                    };
303	                    if let Some(state) = streams.remove(&id) {
304	                        state.control.abort();
305	                    }
306	                }
307	                Ok(())
308	            }
309	            ty if ty == EngineCoreRequestType::Utility.to_frame().as_ref() => {
310	                let (_client_index, call_id, method_name, _args): (
311	                    u32,
312	                    UtilityCallId,
313	                    String,
314	                    rmpv::Value,
315	                ) = rmp_serde::from_slice(&frames[1])?;
316	                send_utility_response(self.engine_index, output_tx, call_id, &method_name)
317	            }
318	            other => bail!("unsupported local engine request type frame: {other:?}"),
319	        }
320	    }
321	
322	    fn start_request(
323	        &self,
324	        request: EngineCoreRequest,
325	        streams: &mut HashMap<RequestId, SteppedStream>,
326	        names: &mut HashMap<String, RequestId>,
327	        output_tx: &tokio::sync::mpsc::UnboundedSender<
328	            vllm_engine_core_client::protocol::output::EngineCoreOutputs,
329	        >,
330	    ) -> Result<()> {
331	        let EngineCoreRequest {
332	            request_id,
333	            prompt_token_ids,
334	            sampling_params,
335	            ..
336	        } = request;
337	        let Some(prompt_tokens) = prompt_token_ids else {
338	            warn!("request {request_id} dropped: missing prompt_token_ids");
339	            return send_terminal_output(
340	                self.engine_index,
341	                output_tx,
342	                request_id,
343	                EngineCoreFinishReason::Error,
344	                None,
345	                None,
346	                None,
347	            );
348	        };
349	        let Some(sampling_params) = sampling_params else {
350	            warn!("request {request_id} dropped: missing sampling_params");
351	            return send_terminal_output(
352	                self.engine_index,
353	                output_tx,
354	                request_id,
355	                EngineCoreFinishReason::Error,
356	                None,
357	                None,
358	                None,
359	            );
360	        };
361	
362	        if let Some(unsupported) = crate::vllm::wire::unsupported_request_params(&sampling_params) {
363	            warn!("request {request_id} rejected: {unsupported}");
364	            return send_terminal_output(
365	                self.engine_index,
366	                output_tx,
367	                request_id,
368	                EngineCoreFinishReason::Error,
369	                None,
370	                None,
371	                None,
372	            );
373	        }
374	
375	        let lora_adapter = match lora_adapter_from_sampling_params(&sampling_params) {
376	            Ok(adapter) => adapter,
377	            Err(error) => {
378	                let message = error.to_string();
379	                warn!("request {request_id} rejected: {message}");
380	                return send_terminal_output(
381	                    self.engine_index,
382	                    output_tx,
383	                    request_id,
384	                    EngineCoreFinishReason::Error,
385	                    Some(StopReason::Text(message)),
386	                    None,
387	                    None,
388	                );
389	            }
390	        };
391	        let extra_arg = |key: &str| {
392	            sampling_params
393	                .extra_args
394	                .as_ref()
395	                .and_then(|args| args.get(key))
396	        };
397	        let kv_transfer_params = extra_arg("kv_transfer_params").cloned();
398	        // The chat layer measured the generation prompt's token count at the
399	        // tail of a prompt only it saw as text; a count the prompt cannot hold
400	        // is no boundary.
401	        let history_tokens = extra_arg(GENERATION_PROMPT_TOKENS)
402	            .and_then(serde_json::Value::as_u64)
403	            .and_then(|tail| prompt_tokens.len().checked_sub(tail as usize));
404	        // The earlier turns' ends the chat layer measured, kept where they
405	        // fall inside this turn's history.
406	        let history_marks: Vec<usize> = extra_arg(HISTORY_MARKS)
407	            .and_then(serde_json::Value::as_array)
408	            .map(|marks| {
409	                marks
410	                    .iter()
411	                    .filter_map(serde_json::Value::as_u64)
412	                    .map(|m| m as usize)
413	                    .filter(|&m| m > 0 && history_tokens.is_some_and(|h| m < h))
414	                    .collect()
415	            })
416	            .unwrap_or_default();
417	        // Older stepped model producers still suppress their terminal token
418	        // and report only `FinishReason::Stop`. Keep the legacy sentinel for
419	        // that producer shape; typed stop causes carry the real token and do
420	        // not need a synthetic suffix.
421	        let stop_sentinel_id = stop_sentinel_id(
422	            sampling_params.eos_token_id,
423	            &sampling_params.stop_token_ids,
424	        );
425	
426	        // Open the request's root span before submit so its context travels
427	        // into the scheduler as the parent of the queue/prefill/decode spans;
428	        // noop (no allocation, `from_span` yields `None`) when tracing is off.
429	        let trace_root = if crate::tracing_state::is_enabled() {
430	            Span::root("request", SpanContext::random())
431	                .with_property(|| ("request_id", request_id.clone()))
432	        } else {
433	            Span::noop()
434	        };
435	        let trace_parent = SpanContext::from_span(&trace_root);
436	
437	        let control = self.scheduler.submit(Request {
438	            prompt_tokens,
439	            // Keep the legacy SamplingParams lowering unchanged for stepped
440	            // producers that have not migrated to StopPolicy. Qwen3 uses the
441	            // independent policy below for stop classification.
442	            params: convert_sampling(&sampling_params),
443	            history_tokens,
444	            history_marks,
445	            stop_policy: convert_stop_policy(&sampling_params),
446	            max_tokens: sampling_params.max_tokens as usize,
447	            lora_adapter,
448	            kv_transfer_params,
449	            logprobs: requested_logprobs(&sampling_params),
450	            prompt_logprobs: requested_prompt_logprobs(&sampling_params),
451	            trace_parent,
452	            client_label: Some(Arc::from(request_id.as_str())),
453	        });
454	
455	        names.insert(request_id.clone(), control.id());
456	        streams.insert(
457	            control.id(),
458	            SteppedStream::new(request_id, control, trace_root, stop_sentinel_id),
459	        );
460	        Ok(())
461	    }
462	}
463	
464	/// Per-request demux state, keyed by the contract's [`RequestId`]; `names`
465	/// maps the vLLM wire's string request id back to it for aborts.
466	struct SteppedStream {
467	    request_id: String,
468	    control: RequestControl,
469	    /// Queued/Scheduled wire events, held until the request's first shipped
470	    /// output (a scheduled-only update produces no request output).
471	    first_token_events: Option<Vec<EngineCoreEvent>>,
472	    /// Set by `Scheduled`; a request refused or failed while still queued
473	    /// never prefilled and reports no prefill stats.
474	    prompt_tokens: Option<usize>,
475	    cached_tokens: usize,
476	    prefill_stats_sent: bool,
477	    /// P/D handoff metadata can arrive in an update with no token or
478	    /// terminal, so retain it until the next output carries it to the router.
479	    kv_transfer_params: Option<serde_json::Value>,
480	    /// Compatibility sentinel for stepped producers that predate typed
481	    /// [`StopCause`]. New producers must include their triggering token in the
482	    /// update and therefore bypass this fallback.
483	    stop_sentinel_id: Option<u32>,
484	    /// Request-lifetime root span; held only for its `Drop`, which closes the
485	    /// trace when the stream state is removed.
486	    #[allow(dead_code)]
487	    trace_root: Span,
488	}
489	
490	impl SteppedStream {
491	    fn new(
492	        request_id: String,
493	        control: RequestControl,
494	        trace_root: Span,
495	        stop_sentinel_id: Option<u32>,
496	    ) -> Self {
497	        Self {
498	            request_id,
499	            control,
500	            first_token_events: None,
501	            prompt_tokens: None,
502	            cached_tokens: 0,
503	            prefill_stats_sent: false,
504	            kv_transfer_params: None,
505	            stop_sentinel_id,
506	            trace_root,
507	        }
508	    }
509	
510	    fn fail_prompt(&mut self, error: &anyhow::Error) -> (Option<EngineCoreOutput>, bool) {
511	        warn!("request {} failed: {error:#}", self.request_id);
512	        self.control.abort();
513	        let output = engine_output(
514	            self.request_id.clone(),
515	            Vec::new(),
516	            None,
517	            Some(EngineCoreFinishReason::Error),
518	            Some(StopReason::Text(error.to_string())),
519	            self.first_token_events.take(),
520	            self.take_prefill_stats(),
521	        );
522	        (Some(output), true)
523	    }
524	
525	    /// Prefill stats for the request's first shipped output. Built lazily so
526	    /// a `cached_tokens` fact arriving after `Scheduled` (chunked prefill
527	    /// reports it with the first chunk) still lands in the stats. Upstream
528	    /// invariant: computed + cached == prompt. `None` for a request that
529	    /// never reached `Scheduled`.
530	    fn take_prefill_stats(&mut self) -> Option<PrefillStats> {
531	        if self.prefill_stats_sent {
532	            return None;
533	        }
534	        let prompt_tokens = self.prompt_tokens?;
535	        self.prefill_stats_sent = true;
536	        Some(PrefillStats {
537	            num_prompt_tokens: prompt_tokens as u32,
538	            num_computed_tokens: prompt_tokens.saturating_sub(self.cached_tokens) as u32,
539	            num_cached_tokens: self.cached_tokens as u32,
540	            num_local_cached_tokens: self.cached_tokens as u32,
541	            num_external_cached_tokens: 0,
542	            num_cache_creation_tokens: 0,
543	        })
544	    }
545	}
546	
547	/// Translate one request's step record into at most one wire output. A
548	/// record carrying only metadata (scheduled, cached, kv-transfer) ships
549	/// nothing; its facts wait in `state` for the first real output. Returns
550	/// `(output, terminated)`.
551	fn reduce_update(
552	    state: &mut SteppedStream,
553	    update: RequestUpdate,
554	    anchor: &UnixAnchor,
555	) -> (Option<EngineCoreOutput>, bool) {
556	    if let Some(scheduled) = update.scheduled {
557	        state.first_token_events = Some(vec![
558	            EngineCoreEvent {
559	                r#type: EngineCoreEventType::Queued,
560	                timestamp: anchor.unix(scheduled.queued_at),
561	            },
562	            EngineCoreEvent {
563	                r#type: EngineCoreEventType::Scheduled,
564	                timestamp: anchor.unix(scheduled.scheduled_at),
565	            },
566	        ]);
567	        state.prompt_tokens = Some(scheduled.prompt_tokens);
568	    }
569	    if let Some(cached) = update.cached_tokens {
570	        state.cached_tokens = cached;
571	    }
572	    if let Some(params) = update.kv_transfer {
573	        state.kv_transfer_params = Some(params);
574	    }
575	    let prompt_logprobs = match update.prompt_echo.map(to_wire_prompt_logprobs).transpose() {
576	        Ok(payload) => payload.flatten(),
577	        Err(error) => return state.fail_prompt(&error),
578	    };
579	
580	    let mut token_ids = update.tokens;
581	    let mut has_logprobs = false;
582	    let mut positions: Vec<PositionLogprobs> = Vec::with_capacity(token_ids.len());
583	    for (i, &id) in token_ids.iter().enumerate() {
584	        let logprob = update.logprobs.get(i).cloned().flatten();
585	        if let Some(position) = to_wire_position_logprobs(id, logprob) {
586	            has_logprobs = true;
587	            positions.push(position);
588	        } else {
589	            positions.push(PositionLogprobs {
590	                entries: Vec::new(),
591	            });
592	        }
593	    }
594	
595	    let mut finish_reason: Option<EngineCoreFinishReason> = None;
596	    let mut stop_reason: Option<StopReason> = None;
597	    let mut terminated = false;
598	    match update.terminal {
599	        None => {}
600	        Some(Terminal::Finished {
601	            reason, stop_cause, ..
602	        }) => {
603	            if reason == FinishReason::Stop
604	                && stop_cause.is_none()
605	                && let Some(stop_sentinel_id) = state.stop_sentinel_id
606	            {
607	                token_ids.push(stop_sentinel_id);
608	                positions.push(PositionLogprobs {
609	                    entries: Vec::new(),
610	                });
611	            }
612	            if let Some(StopCause::Token(token_id)) = stop_cause {
613	                stop_reason = Some(StopReason::TokenId(token_id));
614	            }
615	
616	            finish_reason = Some(convert_finish_reason(reason));
617	            terminated = true;
618	        }
619	        Some(Terminal::Rejected { reason, .. }) => {
620	            // The vLLM wire only carries a string; typed classification stops
621	            // here and the rendered message is what reaches the client.
622	            let message = reason.to_string();
623	            warn!("request {} rejected: {message}", state.request_id);
624	            finish_reason = Some(EngineCoreFinishReason::Error);
625	            stop_reason = Some(StopReason::Text(message));
626	            terminated = true;
627	        }
628	        Some(Terminal::Failed { message, .. }) => {
629	            warn!("request {} failed: {message}", state.request_id);
630	            finish_reason = Some(EngineCoreFinishReason::Error);
631	            stop_reason = Some(StopReason::Text(message));
632	            terminated = true;
633	        }
634	    }
635	
636	    if token_ids.is_empty() && prompt_logprobs.is_none() && !terminated {
637	        return (None, false);
638	    }
639	
640	    let logprobs = has_logprobs.then_some(MaybeWireLogprobs::Direct(Logprobs { positions }));
641	    let mut output = engine_output(
642	        state.request_id.clone(),
643	        token_ids,
644	        logprobs,
645	        finish_reason,
646	        stop_reason,
647	        state.first_token_events.take(),
648	        state.take_prefill_stats(),
649	    );
650	    output.new_prompt_logprobs_tensors = prompt_logprobs;
651	    output.kv_transfer_params = state.kv_transfer_params.take().map(Box::new);
652	    (Some(output), terminated)
653	}
654	
655	/// Renders the contract's monotonic timestamps as wall-clock floats for the
656	/// vLLM wire. One anchor per bridge: both readings taken together at startup,
657	/// so every rendered timestamp shares one clock base.
658	struct UnixAnchor {
659	    sys: f64,
660	    instant: Instant,
661	}
662	
663	impl UnixAnchor {
664	    fn now() -> Self {
665	        Self {
666	            sys: now_secs_f64(),
667	            instant: Instant::now(),
668	        }
669	    }
670	
671	    fn unix(&self, t: Instant) -> f64 {
672	        if t >= self.instant {
673	            self.sys + (t - self.instant).as_secs_f64()
674	        } else {
675	            self.sys - (self.instant - t).as_secs_f64()
676	        }
677	    }
678	}
