405	/// Many requests' tokens in one burst coalesce into a single `EngineCoreOutputs`
406	/// with one `EngineCoreOutput` each, each request's tokens kept in its own
407	/// bucket — the N→1 collapse must never cross-contaminate requests.
408	#[test]
409	fn burst_batches_multiple_requests_into_one_message() {
