411	    d.add("req-a");
412	    d.add("req-b");
413	    d.emit(
414	        "req-a",
415	        TokenEvent::Token {
416	            id: 1,
417	            logprob: None,
418	        },
419	    );
420	    d.emit(
421	        "req-b",
422	        TokenEvent::Token {
423	            id: 2,
424	            logprob: None,
425	        },
426	    );
427	    assert!(d.drain());
428	
429	    let outputs = d.next_output().expect("one coalesced message");
430	    assert_eq!(outputs.outputs.len(), 2);
431	    let a = outputs
432	        .outputs
433	        .iter()
434	        .find(|o| o.request_id == "req-a")
435	        .expect("req-a output");
436	    let b = outputs
437	        .outputs
438	        .iter()
439	        .find(|o| o.request_id == "req-b")
440	        .expect("req-b output");
441	    assert_eq!(a.new_token_ids, vec![1]);
442	    assert_eq!(b.new_token_ids, vec![2]);
443	    assert!(d.next_output().is_none(), "exactly one wire message");
444	}
