446	/// After an abort removes the stream entry, a token already in flight for that
447	/// request is dropped instead of producing a stray output.
448	#[test]
449	fn aborted_request_drops_late_tokens() {
450	    let mut d = Demux::new();
451	    let abort_reason = d.add("req-abort");
452	
453	    // Replicate the Abort handler for a request that already emitted output:
454	    // drop the stream and mark it as cancelled.
455	    RequestAbortReason::Cancelled.store(&abort_reason);
456	    d.streams.remove("req-abort");
457	
458	    d.emit(
459	        "req-abort",
460	        TokenEvent::Token {
461	            id: 99,
462	            logprob: None,
463	        },
464	    );
465	    assert!(d.drain(), "the late event is consumed");
466	    assert!(
467	        d.next_output().is_none(),
468	        "no output is produced for an aborted request"
469	    );
470	}
