472	#[test]
473	fn abort_reason_tracks_first_output_boundary() {
474	    let mut d = Demux::new();
475	    let disconnected = d.add("req-before-output");
476	    let cancelled = d.add("req-after-output");
477	
478	    d.emit(
479	        "req-after-output",
480	        TokenEvent::Token {
481	            id: 7,
482	            logprob: None,
483	        },
484	    );
485	    assert!(d.drain());
486	    assert_eq!(d.next_output().expect("first output").outputs.len(), 1);
487	    assert!(
488	        d.streams
489	            .get("req-after-output")
490	            .is_some_and(|state| state.has_emitted_tokens)
491	    );
492	
493	    let state = d
494	        .streams
495	        .remove("req-before-output")
496	        .expect("disconnect stream");
497	    let reason = if state.has_emitted_tokens {
498	        RequestAbortReason::Cancelled
499	    } else {
500	        RequestAbortReason::Disconnected
501	    };
502	    state.abort(reason);
503	
504	    let state = d.streams.remove("req-after-output").expect("cancel stream");
505	    let reason = if state.has_emitted_tokens {
506	        RequestAbortReason::Cancelled
507	    } else {
508	        RequestAbortReason::Disconnected
509	    };
510	    state.abort(reason);
511	
512	    assert_eq!(
513	        RequestAbortReason::from_raw(disconnected.load(Ordering::Acquire)),
514	        RequestAbortReason::Disconnected
515	    );
516	    assert_eq!(
517	        RequestAbortReason::from_raw(cancelled.load(Ordering::Acquire)),
518	        RequestAbortReason::Cancelled
519	    );
520	}
