522	/// A rejected request (could not be admitted, e.g. too large for the KV cache)
523	/// surfaces to the client as an error with the rejection message, and its stream
524	/// is retired.
525	#[test]
526	fn rejected_request_is_reported_as_error() {
527	    let mut d = Demux::new();
528	    d.add("req-1");
529	    d.emit(
530	        "req-1",
531	        TokenEvent::Rejected {
532	            message: "request is too large for KV cache".to_string(),
533	            prompt_tokens: 16,
534	            completion_tokens: 0,
535	        },
536	    );
537	    assert!(d.drain());
538	
539	    let outputs = d.next_output().expect("terminal output");
540	    assert!(
541	        outputs
542	            .finished_requests
