563	/// The scheduler-stats task turns each load-watch snapshot into a stats-only
564	/// batch (no request outputs, no finished set) with the queue gauges and the
565	/// fractional KV usage the frontend records into Prometheus, sends the current
566	/// snapshot up front, and follows every watch update with exactly one message.
567	#[tokio::test]
568	async fn load_snapshots_become_stats_only_batches() {
569	    let (load_tx, load_rx) = tokio::sync::watch::channel(SchedulerMetrics {
570	        kv_used_blocks: 25,
571	        kv_total_blocks: 100,
572	        num_running_reqs: 2,
573	        num_waiting_reqs: 1,
574	        spec_decode: None,
575	        prefix_cache: None,
576	    });
577	    let (output_tx, mut output_rx) = mpsc::unbounded_channel();
578	    let shutdown = CancellationToken::new();
579	    let task = tokio::spawn(publish_scheduler_stats(
580	        7,
581	        load_rx,
582	        output_tx,
583	        shutdown.clone(),
584	    ));
585	
586	    let batch = match output_rx.recv().await.expect("initial stats batch") {
587	        EngineCoreOutputs::RequestBatch(batch) => batch,
588	        other => panic!("expected a stats batch, got {other:?}"),
589	    };
590	    assert!(batch.outputs.is_empty());
591	    assert!(batch.finished_requests.is_none());
592	    assert_eq!(batch.engine_index, 7);
593	    let stats = batch.scheduler_stats.expect("scheduler stats");
594	    assert_eq!(stats.num_running_reqs, 2);
595	    assert_eq!(stats.num_waiting_reqs, 1);
596	    assert!((stats.kv_cache_usage - 0.25).abs() < 1e-9);
597	
598	    load_tx.send_replace(SchedulerMetrics::default());
599	    let batch = match output_rx.recv().await.expect("drained stats batch") {
600	        EngineCoreOutputs::RequestBatch(batch) => batch,
601	        other => panic!("expected a stats batch, got {other:?}"),
602	    };
603	    let stats = batch.scheduler_stats.expect("scheduler stats");
604	    assert_eq!(stats.num_running_reqs, 0);
605	    assert_eq!(stats.kv_cache_usage.to_bits(), 0.0_f64.to_bits());
606	
607	    shutdown.cancel();
608	    task.await
609	        .expect("stats task exits on shutdown")
610	        .expect("stats publisher shuts down cleanly");
611	}
