613	/// Await one stats-only batch and unwrap its scheduler stats.
614	async fn next_scheduler_stats(
615	    rx: &mut mpsc::UnboundedReceiver<EngineCoreOutputs>,
616	) -> Box<SchedulerStats> {
617	    match rx.recv().await.expect("stats batch") {
618	        EngineCoreOutputs::RequestBatch(batch) => batch.scheduler_stats.expect("scheduler stats"),
619	        other => panic!("expected a stats batch, got {other:?}"),
620	    }
621	}
