623	/// The publisher diffs the scheduler's cumulative totals into the per-interval
624	/// deltas the frontend `inc_by`s, and attaches `spec_decoding_stats` only on
625	/// intervals that actually ran a draft step — an idle interval would divide by
626	/// a zero `num_drafts` in the frontend's acceptance-rate log.
627	#[tokio::test]
628	async fn spec_stats_are_per_interval_deltas_that_skip_idle_intervals() {
629	    let mut totals = SpecDecodeCounters::new(2).expect("K within bounds");
630	    totals.observe_draft(2, 1);
631	    let (load_tx, load_rx) = tokio::sync::watch::channel(SchedulerMetrics {
632	        spec_decode: Some(totals),
633	        ..SchedulerMetrics::default()
634	    });
635	    let (output_tx, mut output_rx) = mpsc::unbounded_channel();
636	    let shutdown = CancellationToken::new();
637	    let task = tokio::spawn(publish_scheduler_stats(
638	        0,
639	        load_rx,
640	        output_tx,
641	        shutdown.clone(),
642	    ));
643	
644	    // First publish diffs against zero, so it carries the whole cumulative.
645	    let first = next_scheduler_stats(&mut output_rx).await;
646	    let spec = first
647	        .spec_decoding_stats
648	        .expect("first interval has a draft");
649	    assert_eq!(spec.num_spec_tokens, 2);
650	    assert_eq!(spec.num_drafts, 1);
651	    assert_eq!(spec.num_accepted_tokens, 1);
652	    // Widened to the drafter's K, not the array's.
653	    assert_eq!(spec.num_accepted_tokens_per_pos, vec![1, 0]);
654	
655	    // A no-op republish (same totals) is an idle interval: no spec stats.
656	    load_tx.send_replace(SchedulerMetrics {
657	        spec_decode: Some(totals),
658	        num_running_reqs: 1,
659	        ..SchedulerMetrics::default()
660	    });
661	    let idle = next_scheduler_stats(&mut output_rx).await;
662	    assert!(idle.spec_decoding_stats.is_none());
663	
664	    // Two verify steps land in one snapshot — the watch coalesced them. The
665	    // delta has to cover the whole gap, per position as well as in total,
666	    // which is the reason the transport carries totals instead of deltas.
667	    totals.observe_draft(2, 2);
668	    totals.observe_draft(2, 2);
669	    load_tx.send_replace(SchedulerMetrics {
670	        spec_decode: Some(totals),
671	        ..SchedulerMetrics::default()
672	    });
673	    let resumed = next_scheduler_stats(&mut output_rx).await;
674	    let spec = resumed.spec_decoding_stats.expect("second draft interval");
675	    assert_eq!(spec.num_drafts, 2);
676	    assert_eq!(spec.num_draft_tokens, 4);
677	    assert_eq!(spec.num_accepted_tokens, 4);
678	    assert_eq!(spec.num_accepted_tokens_per_pos, vec![2, 2]);
679	
680	    shutdown.cancel();
681	    task.await
682	        .expect("stats task exits on shutdown")
683	        .expect("stats publisher shuts down cleanly");
684	}
685	
686	/// Prefix-cache totals become per-interval deltas that the frontend `inc_by`s
687	/// into `vllm:prefix_cache_{queries,hits}_total` for the device tier and, via
688	/// the connector stats, `vllm:external_prefix_cache_*` and
689	/// `prompt_tokens_cached_by_source{source="host"}` for the host tier, or
690	/// `source="external_unspecified"` when the engine cannot attribute them. An
691	/// engine restart (totals going backwards) diffs from zero instead of going
692	/// negative, and an engine without a prefix cache exports zeros as before.
693	#[tokio::test]
694	async fn prefix_cache_stats_are_per_interval_deltas_across_a_restart() {
695	    let mut totals = PrefixCacheCounters {
696	        queries: 4096,
697	        ..PrefixCacheCounters::default()
698	    };
699	    let (load_tx, load_rx) = tokio::sync::watch::channel(SchedulerMetrics {
700	        prefix_cache: Some(totals),
701	        ..SchedulerMetrics::default()
702	    });
703	    let (output_tx, mut output_rx) = mpsc::unbounded_channel();
704	    let shutdown = CancellationToken::new();
705	    let task = tokio::spawn(publish_scheduler_stats(
706	        0,
707	        load_rx,
708	        output_tx,
709	        shutdown.clone(),
710	    ));
711	
712	    // First publish diffs against zero, so it carries the whole cumulative.
713	    let first = next_scheduler_stats(&mut output_rx).await;
714	    assert_eq!(first.prefix_cache_stats.base.queries, 4096);
715	    assert_eq!(first.prefix_cache_stats.base.hits, 0);
716	    // No host lookup yet: no external stats.
717	    assert_eq!(first.connector_prefix_cache_stats, None);
718	
719	    // A later turn: 4352 tokens looked up, 4096 of them served from cache;
720	    // the 1280 that missed device were looked up in host, which had 1024.
721	    totals.queries += 4352;
722	    totals.hits += 4096;
723	    totals.host_queries += 1280;
724	    totals.host_hits += 1024;
725	    load_tx.send_replace(SchedulerMetrics {
726	        prefix_cache: Some(totals),
727	        ..SchedulerMetrics::default()
728	    });
729	    let turn = next_scheduler_stats(&mut output_rx).await;
730	    let local = &turn.prefix_cache_stats;
731	    assert_eq!(local.base.queries, 4352);
732	    assert_eq!(local.base.hits, 3072);
733	    let host = turn
734	        .connector_prefix_cache_stats
735	        .as_ref()
736	        .expect("host hits ride the connector stats");
737	    assert_eq!(host.base.queries, 1280);
738	    assert_eq!(host.base.hits, 1024);
739	    assert_eq!(host.hits_by_source.host, 1024);
740	    // What the frontend adds to `prompt_tokens_cached_by_source`: local hits
741	    // as `device`, connector hits by their source. Together, every hit once.
742	    let mut by_source = host.hits_by_source.counts();
743	    by_source[0] += local.base.hits;
744	    assert_eq!(by_source, [3072, 1024, 0, 0, 0]);
745	    assert_eq!(by_source.iter().sum::<u64>(), 4096);
746	
747	    // Another turn whose connector restores 512 tokens from a tier it cannot
748	    // name: the hits are external, labeled `external_unspecified`, and stay
749	    // out of both the local hits and the `host` label.
750	    totals.queries += 2048;
751	    totals.hits += 1536;
752	    totals.host_queries += 1024;
753	    totals.external_unspecified_hits += 512;
754	    load_tx.send_replace(SchedulerMetrics {
755	        prefix_cache: Some(totals),
756	        ..SchedulerMetrics::default()
757	    });
758	    let unspecified = next_scheduler_stats(&mut output_rx).await;
759	    assert_eq!(unspecified.prefix_cache_stats.base.queries, 2048);
760	    assert_eq!(unspecified.prefix_cache_stats.base.hits, 1024);
761	    let external = unspecified
762	        .connector_prefix_cache_stats
763	        .as_ref()
764	        .expect("unattributed hits ride the connector stats");
765	    assert_eq!(external.base.queries, 1024);
766	    assert_eq!(external.base.hits, 512);
767	    assert_eq!(external.hits_by_source.external_unspecified, 512);
768	    assert_eq!(external.hits_by_source.host, 0);
769	    let mut by_source = external.hits_by_source.counts();
770	    by_source[0] += unspecified.prefix_cache_stats.base.hits;
771	    assert_eq!(by_source, [1024, 0, 0, 0, 512]);
772	    assert_eq!(by_source.iter().sum::<u64>(), 1536);
773	
774	    // The engine restarts: totals fall below the baseline. The interval
775	    // counts from zero rather than underflowing or dropping the new work.
776	    load_tx.send_replace(SchedulerMetrics {
777	        prefix_cache: Some(PrefixCacheCounters {
778	            queries: 300,
779	            hits: 200,
780	            ..PrefixCacheCounters::default()
781	        }),
782	        ..SchedulerMetrics::default()
783	    });
784	    let restarted = next_scheduler_stats(&mut output_rx).await;
785	    assert_eq!(restarted.prefix_cache_stats.base.queries, 300);
786	    assert_eq!(restarted.prefix_cache_stats.base.hits, 200);
787	    assert_eq!(restarted.connector_prefix_cache_stats, None);
788	
789	    // No prefix cache: the default stats, exactly what was exported before.
790	    load_tx.send_replace(SchedulerMetrics::default());
791	    let none = next_scheduler_stats(&mut output_rx).await;
792	    assert_eq!(none.prefix_cache_stats, PrefixCacheStats::default());
793	    assert_eq!(none.connector_prefix_cache_stats, None);
794	
795	    shutdown.cancel();
796	    task.await
797	        .expect("stats task exits on shutdown")
798	        .expect("stats publisher shuts down cleanly");
799	}
