1	//! Focused tests over the real `dispatch_burst` / `reduce_request` demux — fed
2	//! actual `TokenEvent`s, asserting on actual `EngineCoreOutputs`, no mocks. They
3	//! pin what the HTTP layer structurally can't observe: cross-request bucketing,
4	//! first-token metadata riding the first output exactly once, prefill-cache
5	//! accounting (`UsageInfo` is built from raw counts and never reads
6	//! `prefill_stats`, so cached/computed surface only here and in Prometheus), and
7	//! abort dropping late tokens. The full HTTP→ZMQ→bridge happy path is covered
8	//! end to end by `pegainfer-sim`'s `frontend_e2e` integration test (the CI gate).
9	
10	use std::sync::atomic::Ordering;
11	
12	use super::*;
13	use crate::engine::FinishReason;
14	use crate::engine::RequestAbortReason;
15	use crate::engine::TokenLogprob;
16	
17	/// Test harness that exercises the bridge's demux path directly: register
18	/// requests, emit tagged events onto the shared channel, drain one ready
19	/// burst at a time, and inspect the coalesced outputs — the same flow the
20	/// `run` loop drives, minus the sockets.
21	struct Demux {
22	    event_tx: mpsc::UnboundedSender<(RequestTag, TokenEvent)>,
23	    event_rx: TokenStreamReceiver,
24	    streams: HashMap<RequestTag, RequestStreamState>,
25	    output_tx: mpsc::UnboundedSender<EngineCoreOutputs>,
26	    output_rx: mpsc::UnboundedReceiver<EngineCoreOutputs>,
27	}
28	
29	impl Demux {
30	    fn new() -> Self {
31	        let (event_tx, event_rx) = mpsc::unbounded_channel();
32	        let (output_tx, output_rx) = mpsc::unbounded_channel();
33	        Self {
34	            event_tx,
35	            event_rx,
36	            streams: HashMap::new(),
37	            output_tx,
38	            output_rx,
39	        }
40	    }
41	
42	    /// Register a request as `start_request` does and return its abort reason.
43	    fn add(&mut self, id: &str) -> Arc<AtomicU8> {
44	        self.add_with_stop_sentinel(id, None)
45	    }
46	
47	    fn add_with_eos(&mut self, id: &str, eos_token_id: Option<u32>) -> Arc<AtomicU8> {
48	        self.add_with_stop_sentinel(id, eos_token_id)
49	    }
50	
51	    fn add_with_stop_sentinel(&mut self, id: &str, stop_sentinel_id: Option<u32>) -> Arc<AtomicU8> {
52	        let tag: RequestTag = Arc::from(id);
53	        let abort_reason = Arc::new(AtomicU8::new(RequestAbortReason::None as u8));
54	        self.streams.insert(
55	            Arc::clone(&tag),
56	            RequestStreamState::new(
57	                Arc::clone(&abort_reason),
58	                fastrace::Span::noop(),
59	                stop_sentinel_id,
60	            ),
61	        );
62	        abort_reason
63	    }
64	
65	    fn emit(&self, id: &str, event: TokenEvent) {
66	        self.event_tx
67	            .send((Arc::from(id), event))
68	            .expect("emit token event");
69	    }
70	
71	    /// Process one ready burst. Returns false if nothing was queued.
72	    fn drain(&mut self) -> bool {
73	        match self.event_rx.try_recv() {
74	            Ok(first) => {
75	                dispatch_burst(
76	                    0,
77	                    first,
78	                    &mut self.event_rx,
79	                    &mut self.streams,
80	                    &self.output_tx,
81	                )
82	                .expect("dispatch burst");
83	                true
84	            }
85	            Err(_) => false,
86	        }
87	    }
88	
89	    fn next_output(&mut self) -> Option<RequestBatchOutputs> {
90	        let outputs = self.output_rx.try_recv().ok()?;
91	        match outputs {
92	            EngineCoreOutputs::RequestBatch(batch) => Some(batch),
93	            other => panic!("expected a request batch, got {other:?}"),
94	        }
95	    }
96	}
